import { useId, useRef, useState, type KeyboardEvent } from 'react';

export type Item = {
  id: string;
  title: string;
  body: string;
  disabled?: boolean;
};
export type Props = { items: Item[] };

export function Component({ items }: Props) {
  const prefix = useId();
  const [openId, setOpenId] = useState<string | null>(null);
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const enabled = items.filter(item => !item.disabled);

  function moveFocus(event: KeyboardEvent<HTMLButtonElement>, id: string) {
    if (
      event.key !== 'ArrowDown' &&
      event.key !== 'ArrowUp' &&
      event.key !== 'Home' &&
      event.key !== 'End'
    ) {
      return;
    }

    event.preventDefault();
    if (enabled.length === 0) return;

    const index = enabled.findIndex(item => item.id === id);
    if (index < 0) return;

    let targetIndex: number;
    switch (event.key) {
      case 'ArrowDown':
        targetIndex = (index + 1) % enabled.length;
        break;
      case 'ArrowUp':
        targetIndex = (index - 1 + enabled.length) % enabled.length;
        break;
      case 'Home':
        targetIndex = 0;
        break;
      default:
        targetIndex = enabled.length - 1;
    }

    const target = enabled[targetIndex];
    if (target) buttons.current.get(target.id)?.focus();
  }

  return (
    <div>
      {items.map((item, index) => {
        const buttonId = `${prefix}-button-${index}`;
        const panelId = `${prefix}-panel-${index}`;
        const expanded = openId === item.id && !item.disabled;

        return (
          <div key={item.id}>
            <h3>
              <button
                ref={node => {
                  if (node) buttons.current.set(item.id, node);
                  else buttons.current.delete(item.id);
                }}
                id={buttonId}
                type="button"
                disabled={item.disabled}
                aria-expanded={expanded}
                aria-controls={panelId}
                onKeyDown={event => moveFocus(event, item.id)}
                onClick={() => {
                  if (item.disabled) return;
                  setOpenId(current => current === item.id ? null : item.id);
                }}
              >
                {item.title}
              </button>
            </h3>
            {expanded && (
              <div id={panelId} role="region" aria-labelledby={buttonId}>
                {item.body}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
